{
  "appearance_facts": [
    {
      "location": "A single blue line spans the plot from the left edge to the right edge.",
      "fact": "The line starts low on the left, rises steadily to a peak near the right, then dips slightly at the final point."
    },
    {
      "location": "The line's lowest point is at the far left (1880) and its highest point is near the far right (1890).",
      "fact": "The overall shape is an upward trend with a small drop only at the very end."
    },
    {
      "location": "Between 1882 and 1884 the line shows a small local dip and then resumes rising.",
      "fact": "There is a minor plateau/dip in the early-middle section, but the long-term direction is upward."
    },
    {
      "location": "The line reaches its maximum height at the second-to-last x-position (1890).",
      "fact": "The peak value is visually the highest point on the chart, above the 3,000 gridline."
    },
    {
      "location": "The final segment (1890 to 1891) slopes downward.",
      "fact": "Only the last year shows a decrease, dropping from the peak but still remaining near the top of the chart."
    }
  ],
  "printed_facts": [
    {
      "location": "Chart title at the top: 'Decreasing Number of New Tourists in Town Z from 1880 to 1891'.",
      "fact": "The title text states 'Decreasing', which conflicts with the visual line that rises from ~950 to ~3,100."
    },
    {
      "location": "Y-axis label: 'Number of Tourists'; tick labels 0, 500, 1,000, 1,500, 2,000, 2,500, 3,000.",
      "fact": "The vertical scale is in whole tourist counts with 500-unit increments."
    },
    {
      "location": "X-axis label: 'Year'; tick labels 1880 through 1891 in single-year steps.",
      "fact": "The horizontal axis covers 1880-1891."
    },
    {
      "location": "Line value at 1880 (leftmost point).",
      "fact": "Approximately 950-1,000 tourists, just below the 1,000 tick."
    },
    {
      "location": "Line value at 1882.",
      "fact": "Approximately 1,700 tourists."
    },
    {
      "location": "Line value at 1883.",
      "fact": "Approximately 1,600-1,650 tourists (slight dip from 1882)."
    },
    {
      "location": "Line value at 1886.",
      "fact": "Approximately 2,450-2,500 tourists."
    },
    {
      "location": "Line value at 1890 (peak).",
      "fact": "Approximately 3,100 tourists, the highest point on the chart."
    }
  ],
  "public_definitions": [
    "Option 'Route to tourism growth planning' is one of the three routing choices for the tourism trend.",
    "Option 'Route to tourism decline response' is one of the three routing choices for the tourism trend.",
    "Option 'Keep on routine tourism monitoring' is one of the three routing choices for the tourism trend.",
    "The task instruction is to use the Town Z new-tourist dashboard as the evidence source for the tourism trend routing decision."
  ],
  "uncertain": [
    "The chart title says 'Decreasing' but the plotted line clearly increases over 1880-1891; it is unclear whether the title is a mislabel or whether a different (unplotted) series was intended.",
    "No exact data labels are printed on the line, so all point values are estimated from gridline alignment.",
    "The 1891 endpoint value is not labeled; it appears to be around 2,900-2,950, but this is an estimate."
  ]
}
